insert into species (id, common_name, latin_name, edibility_status, requires_cooking, prep_instructions, lookalike_species_ids, toxicity_notes, poisoning_history, habitat, season, region, photo_urls, confidence_notes, cooking_methods)
values
  ('chanterelle', 'Chanterelle', 'Cantharellus cibarius', 'edible', false, NULL, ARRAY['false-chanterelle', 'jack-o-lantern']::text[], NULL, 'No significant poisoning history; one of Europe''s most widely foraged edibles.', 'Mixed and coniferous forest, often near oak, beech, or pine', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/chanterelle/800/800']::text[], 'True gills are shallow, forked, and run down the stem (not true gills but ridges); distinct apricot smell. Solid flesh throughout, unlike hollow-stemmed look-alikes.', '[{"method":"Dry sauté","detail":"Chanterelles hold a lot of water. Dry-fry in a hot pan with no fat until the water releases and boils off, then add butter and finish. Adding fat too early steams them."},{"method":"Butter and cream","detail":"Classic finish: butter, shallot, a splash of cream. Their apricot note suits eggs and poultry."},{"method":"Freeze (cooked)","detail":"Freeze only after cooking. Raw frozen chanterelles turn bitter and mushy."}]'::jsonb),
  ('false-chanterelle', 'False Chanterelle', 'Hygrophoropsis aurantiaca', 'inedible', false, NULL, ARRAY['chanterelle']::text[], 'Not deadly, but has caused gastrointestinal upset in some people and is generally considered not worth eating.', 'Occasional mild GI illness reported; not associated with severe or fatal poisoning.', 'Coniferous woodland, on decaying wood or needle litter', 'Summer to late autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/false-chanterelle/800/800']::text[], 'Has true, thin, closely-spaced gills (vs. the chanterelle''s blunt forked ridges) and a deeper orange color.', '[]'::jsonb),
  ('jack-o-lantern', 'Jack-o''-Lantern', 'Omphalotus illudens', 'toxic', false, NULL, ARRAY['chanterelle']::text[], 'Causes severe cramping, vomiting, and diarrhea. Gills are famously bioluminescent (faintly glow in complete darkness), unlike any chanterelle.', 'A common cause of non-fatal but severe GI poisoning where foragers mistake it for chanterelles.', 'Dense clusters at the base of hardwood trees or on buried roots/stumps', 'Late summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/jack-o-lantern/800/800']::text[], 'Grows in dense clumps from wood, has true thin gills, and lacks the chanterelle''s apricot smell - chanterelles grow singly or scattered from soil.', '[]'::jsonb),
  ('death-cap', 'Death Cap', 'Amanita phalloides', 'deadly', false, NULL, ARRAY['field-mushroom', 'horse-mushroom']::text[], 'Contains amatoxins that cause severe, often irreversible liver and kidney damage. Symptoms are delayed 6-24 hours, often after damage is already underway. No amount of cooking, drying, or freezing makes it safe.', 'Responsible for the majority of fatal mushroom poisonings worldwide, according to mycological and poison-control literature.', 'Deciduous woodland, especially near oak', 'Late summer to autumn', 'Europe, widely introduced elsewhere', ARRAY['https://picsum.photos/seed/death-cap/800/800']::text[], 'Always check the stem base: a white, sack-like volva (often underground) plus white gills and a ring are key warning signs shared with other deadly Amanita species.', '[]'::jsonb),
  ('destroying-angel', 'Destroying Angel', 'Amanita virosa', 'deadly', false, NULL, ARRAY['field-mushroom', 'horse-mushroom', 'giant-puffball']::text[], 'Pure white, contains the same amatoxins as the Death Cap. As dangerous, and easily mistaken for young field or horse mushrooms before the cap opens, or for an unopened puffball if not cut in half.', 'Documented fatalities across Europe and North America; consistently listed alongside Death Cap as the most dangerous foraging mistake.', 'Coniferous and mixed woodland', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/destroying-angel/800/800']::text[], 'Always cut any round white ''puffball'' in half before eating: a developing Amanita shows a visible mushroom outline inside, a true puffball is uniform white flesh throughout.', '[]'::jsonb),
  ('morel', 'Morel', 'Morchella esculenta', 'edible_cooked', true, 'Cook thoroughly - never eat raw. Sauteing or boiling for several minutes destroys the mild hydrazine-related toxins present in raw morels.', ARRAY['false-morel']::text[], NULL, 'Generally safe when cooked; raw or undercooked consumption has caused gastrointestinal illness.', 'Disturbed ground, old orchards, recently burned forest', 'Spring', 'Europe, North America', ARRAY['https://picsum.photos/seed/morel/800/800']::text[], 'Cap is honeycombed with pits and ridges and is fully hollow, including where it joins the stem - cut it lengthwise to check.', '[{"method":"Sauté (essential)","detail":"Never eat raw. Sauté at least 5-10 minutes until fully cooked through - raw morels cause GI illness even in people who tolerate them cooked."},{"method":"Dry for storage","detail":"Dries exceptionally well and intensifies in flavour. Rehydrate in warm water, and cook the rehydrated mushroom thoroughly."},{"method":"Cream sauce","detail":"Cooked morels finished with cream and stock is the traditional preparation."}]'::jsonb),
  ('false-morel', 'False Morel', 'Gyromitra esculenta', 'toxic', false, 'Traditionally parboiled with the water discarded in some Nordic regions, but toxin content is unpredictable and the parboiling water''s fumes are themselves hazardous - not recommended for consumption.', ARRAY['morel']::text[], 'Contains gyromitrin, which the body converts to a toxic compound in the same chemical family as rocket fuel (monomethylhydrazine). Toxicity varies unpredictably by specimen, region, and preparation.', 'Documented fatalities in Europe, particularly historically in Scandinavia and Eastern Europe from consumption without proper preparation.', 'Sandy soil under conifers, especially after fire', 'Spring', 'Northern Europe, North America', ARRAY['https://picsum.photos/seed/false-morel/800/800']::text[], 'Cap is a reddish-brown, wrinkled ''brain'' shape rather than a regular honeycomb, and the interior is chambered/cottony rather than cleanly hollow like a true morel.', '[]'::jsonb),
  ('porcini', 'Porcini', 'Boletus edulis', 'edible', false, NULL, ARRAY['bitter-bolete', 'satans-bolete']::text[], NULL, 'Widely and safely consumed across Europe; no notable poisoning history.', 'Coniferous and deciduous forest', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/porcini/800/800']::text[], 'White pore surface when young (aging to olive-yellow), a fine white network pattern on the upper stem, and flesh that does not change color when cut.', '[{"method":"Pan-sear","detail":"Slice thickly and sear in butter or oil until golden. Young firm caps take heat best."},{"method":"Dry","detail":"The classic preservation method - drying deepens the flavour considerably. Rehydrate and keep the soaking liquid for stock."},{"method":"Raw (young only)","detail":"Very young, firm, insect-free specimens are sometimes shaved raw into salads. Only do this if you are completely certain of the identification."}]'::jsonb),
  ('bitter-bolete', 'Bitter Bolete', 'Tylopilus felleus', 'inedible', false, NULL, ARRAY['porcini']::text[], 'Not toxic, but intensely bitter - a single specimen can ruin an entire dish. The bitterness does not cook out.', 'No poisoning risk; the harm is culinary, not medical. Frequently picked by mistake in place of porcini.', 'Coniferous and deciduous forest, often near stumps', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/bitter-bolete/800/800']::text[], 'Pink (not white) pore surface at maturity, a coarse dark network on the stem instead of porcini''s fine white one, and flesh that browns/pinks when cut. Taste a tiny piece and spit it out - if it''s bitter, it''s this species.', '[]'::jsonb),
  ('satans-bolete', 'Satan''s Bolete', 'Rubroboletus satanas', 'toxic', false, NULL, ARRAY['porcini', 'bay-bolete']::text[], 'Causes severe gastrointestinal symptoms. Red pore surface and flesh that turns blue rapidly when cut distinguish it from porcini and bay bolete.', 'A well-documented cause of severe, though rarely fatal, GI poisoning in Central and Southern Europe.', 'Calcareous soil under broadleaf trees, especially oak and beech', 'Summer to early autumn', 'Southern and Central Europe', ARRAY['https://picsum.photos/seed/satans-bolete/800/800']::text[], 'Distinctive red-to-orange pore surface and a bulbous, red-netted stem; flesh bruises blue within seconds of cutting.', '[]'::jsonb),
  ('bay-bolete', 'Bay Bolete', 'Imleria badia', 'edible', false, NULL, ARRAY['satans-bolete']::text[], NULL, 'No significant poisoning history; a popular edible throughout Europe.', 'Coniferous and mixed woodland', 'Summer to autumn', 'Europe', ARRAY['https://picsum.photos/seed/bay-bolete/800/800']::text[], 'Chestnut-brown cap, yellowish pore surface that bruises blue-green (but not as dramatically as Satan''s Bolete), and a smooth, unnetworked stem.', '[{"method":"Pan-fry","detail":"Fries well; the flesh stays firmer than most boletes. Remove the pore layer on older specimens - it goes slimy."},{"method":"Dry","detail":"Dries well, though with less intensity than porcini."}]'::jsonb),
  ('birch-bolete', 'Birch Bolete', 'Leccinum scabrum', 'edible', false, NULL, '{}', NULL, 'No significant poisoning history.', 'Exclusively under birch trees', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/birch-bolete/800/800']::text[], 'Stem covered in small dark scales (''scabers''); only grows near birch, which narrows identification considerably.', '[{"method":"Cook thoroughly","detail":"Softer than porcini and goes mushy easily - best in soups, stews, or sauces rather than pan-fried alone."},{"method":"Dry","detail":"Dries acceptably. Discard the spongy pore layer on older specimens first."}]'::jsonb),
  ('orange-birch-bolete', 'Orange Birch Bolete', 'Leccinum versipelle', 'edible_cooked', true, 'Cook well before eating - like other Leccinum boletes it can cause mild GI upset if undercooked.', '{}', NULL, 'Occasional mild GI upset if undercooked; otherwise a popular edible.', 'Exclusively under birch trees', 'Summer to autumn', 'Northern and Central Europe', ARRAY['https://picsum.photos/seed/orange-birch-bolete/800/800']::text[], 'Bright orange cap and scabered stem that darkens sharply when cut.', '[{"method":"Cook well (required)","detail":"Cook thoroughly - like other Leccinum boletes it can cause GI upset when undercooked. Do not eat rare."},{"method":"Stews and soups","detail":"The flesh darkens to near-black when cooked, which is normal. Suits robust dishes."}]'::jsonb),
  ('hedgehog-mushroom', 'Hedgehog Mushroom', 'Hydnum repandum', 'edible', false, NULL, '{}', NULL, 'No significant poisoning history; the tooth-fungus family has no seriously toxic look-alikes in Europe.', 'Mixed woodland, on soil', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/hedgehog-mushroom/800/800']::text[], 'Distinctive soft spines instead of gills or pores on the underside of the cap - unmistakable once checked.', '[{"method":"Pan-fry","detail":"Firm texture that holds up well to frying. Older specimens can be slightly bitter - blanch briefly first if so."},{"method":"Scrape the spines","detail":"The spines drop off when cooking and can make a sauce gritty; scrape them off first for delicate dishes."}]'::jsonb),
  ('black-trumpet', 'Black Trumpet', 'Craterellus cornucopioides', 'edible', false, NULL, '{}', NULL, 'No significant poisoning history; prized edible with no dangerous European look-alikes.', 'Deciduous woodland, especially near oak and beech, in shaded damp spots', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/black-trumpet/800/800']::text[], 'Thin, dark grey-brown, trumpet-shaped and hollow throughout; easy to overlook against leaf litter.', '[{"method":"Dry","detail":"Dries superbly and the flavour concentrates into something close to truffle. Grind dried ones into a powder for seasoning."},{"method":"Sauté","detail":"Rinse carefully - grit and insects hide in the hollow trumpet - then sauté in butter."}]'::jsonb),
  ('cauliflower-fungus', 'Cauliflower Fungus', 'Sparassis crispa', 'edible', false, NULL, '{}', NULL, 'No significant poisoning history.', 'Base of pine trees', 'Late summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/cauliflower-fungus/800/800']::text[], 'Large, pale, brain-like mass of flattened ribbons growing at a pine base - visually distinctive.', '[{"method":"Wash thoroughly first","detail":"The ribbon folds trap pine needles and grit. Soak and rinse repeatedly before cooking."},{"method":"Sauté or braise","detail":"Firm, almost noodle-like texture that holds its shape well. Young specimens are best; older ones toughen."}]'::jsonb),
  ('giant-puffball', 'Giant Puffball', 'Calvatia gigantea', 'edible', false, 'Only eat when young: the flesh must be pure white and firm throughout when cut in half. Any yellowing, discoloration, or a visible mushroom shape inside means it''s past safe eating or is a different species entirely.', ARRAY['destroying-angel']::text[], 'The puffball itself is safe when young and pure white inside, but immature (egg-stage) specimens of deadly Amanita species can superficially resemble a small puffball from the outside.', 'Poisonings attributed to this species are almost always cases of a deadly Amanita ''egg'' mistaken for a small puffball because it wasn''t cut open first.', 'Meadows, pastures, and forest edges', 'Late summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/giant-puffball/800/800']::text[], 'Always slice any puffball-like find in half top to bottom before eating: uniform white flesh throughout is a true puffball; any internal outline of a cap, gills, or stem means it is something else entirely - do not eat it.', '[{"method":"Slice and fry","detail":"Cut into thick slabs and fry like a steak or schnitzel. Only use flesh that is pure white throughout."},{"method":"Do not dry","detail":"Does not dry or freeze well - the texture collapses. Eat fresh, within a day or two."}]'::jsonb),
  ('field-mushroom', 'Field Mushroom', 'Agaricus campestris', 'edible', false, NULL, ARRAY['yellow-stainer', 'destroying-angel', 'death-cap']::text[], NULL, 'Safe and widely eaten, but responsible for indirect poisonings when confused with deadly Amanita species or the Yellow Stainer.', 'Grassy meadows and pastures', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/field-mushroom/800/800']::text[], 'Always check the stem base for a volva (sack) - a true field mushroom has none. Gills are pink, darkening to chocolate-brown with age, never pure white.', '[{"method":"Grill or fry","detail":"Treat like a shop-bought mushroom, which it is closely related to. Grilling whole caps concentrates the flavour."},{"method":"Check for maggots","detail":"Field mushrooms are frequently infested. Halve each one and inspect before cooking."}]'::jsonb),
  ('horse-mushroom', 'Horse Mushroom', 'Agaricus arvensis', 'edible', false, NULL, ARRAY['yellow-stainer', 'destroying-angel', 'death-cap']::text[], NULL, 'Safe and widely eaten, but subject to the same confusion risks as the Field Mushroom.', 'Grassy meadows, pastures, and woodland edges', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/horse-mushroom/800/800']::text[], 'Larger than the Field Mushroom with a faint aniseed smell; check for a volva at the base and pink-to-brown (never white) gills.', '[{"method":"Grill or stuff","detail":"Large caps suit stuffing and grilling. The faint aniseed note cooks off into something mild and nutty."},{"method":"Cook young","detail":"Best while the gills are still pink. Older specimens can be strong and are often infested."}]'::jsonb),
  ('yellow-stainer', 'Yellow Stainer', 'Agaricus xanthodermus', 'toxic', false, NULL, ARRAY['field-mushroom', 'horse-mushroom']::text[], 'Causes gastrointestinal upset (nausea, vomiting, cramping) in most people who eat it, though a minority tolerate it - not worth the risk.', 'One of the most common causes of mushroom-related GI illness call-outs in the UK and Europe, almost always from confusion with field or horse mushrooms.', 'Grassy areas, gardens, woodland edges', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/yellow-stainer/800/800']::text[], 'Cut or bruise the base of the stem: a bright chrome-yellow stain plus an unpleasant, ink-like or chemical smell (especially on cooking) are the giveaways - a genuine field mushroom does not do this.', '[]'::jsonb),
  ('parasol-mushroom', 'Parasol Mushroom', 'Macrolepiota procera', 'edible_cooked', true, 'Best cooked; the large cap is traditionally breaded and fried. Only eat the cap - the fibrous stem is not palatable.', ARRAY['shaggy-parasol', 'deadly-dapperling']::text[], NULL, 'Safe and popular when correctly identified; danger comes almost entirely from confusion with small deadly Lepiota species.', 'Grassy fields, pastures, woodland edges', 'Summer to autumn', 'Europe', ARRAY['https://picsum.photos/seed/parasol-mushroom/800/800']::text[], 'Grows large (cap can exceed 20cm) on a tall, slender, snakeskin-patterned stem with a free-moving double ring. Size alone rules out the much smaller Deadly Dapperling.', '[{"method":"Breaded and fried","detail":"The classic preparation: coat the whole cap in egg and breadcrumbs and shallow-fry like a schnitzel."},{"method":"Cap only","detail":"Discard the stem entirely - it is fibrous and woody regardless of cooking."}]'::jsonb),
  ('shaggy-parasol', 'Shaggy Parasol', 'Chlorophyllum rhacodes', 'edible_cooked', true, 'Cook thoroughly and try only a small amount the first time - a meaningful minority of people react with GI upset even when properly cooked.', ARRAY['parasol-mushroom', 'deadly-dapperling']::text[], NULL, 'Causes gastrointestinal reactions in a notable fraction of eaters even when cooked; considered edible but with a documented intolerance rate.', 'Gardens, parks, woodland edges, often in rings', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/shaggy-parasol/800/800']::text[], 'Shorter and stockier than the true Parasol, with flesh that reddens when cut; ring is not free-moving on the stem like the Parasol''s.', '[{"method":"Cook thoroughly, try a little first","detail":"Cook well, and eat only a small portion the first time. A meaningful minority of people get GI upset from this species even properly cooked."},{"method":"Breaded and fried","detail":"Same preparation as the true Parasol - cap only, stem discarded."}]'::jsonb),
  ('deadly-dapperling', 'Deadly Dapperling', 'Lepiota brunneoincarnata', 'deadly', false, NULL, ARRAY['parasol-mushroom', 'shaggy-parasol']::text[], 'Contains the same amatoxins as the Death Cap. Small size means a handful of specimens can deliver a fatal dose.', 'Documented fatalities in Southern and Central Europe, typically from foragers mistaking young specimens for edible Lepiota/Macrolepiota species.', 'Grassy areas, gardens, parks', 'Summer to autumn', 'Southern and Central Europe', ARRAY['https://picsum.photos/seed/deadly-dapperling/800/800']::text[], 'Much smaller than a true Parasol (cap rarely exceeds 5cm) with a reddish-brown scaly cap - size is the fastest red flag.', '[]'::jsonb),
  ('saffron-milkcap', 'Saffron Milkcap', 'Lactarius deliciosus', 'edible', false, NULL, ARRAY['woolly-milkcap']::text[], NULL, 'No significant poisoning history; popular edible especially in Southern Europe.', 'Coniferous forest, especially under pine', 'Autumn', 'Europe', ARRAY['https://picsum.photos/seed/saffron-milkcap/800/800']::text[], 'Bleeds a distinctive orange ''milk'' when cut that slowly turns green; concentric orange zoning on the cap.', '[{"method":"Grill or pan-fry","detail":"Traditional in Spain and Catalonia grilled over coals with garlic, oil, and parsley. Firm texture, slightly grainy."},{"method":"Preserve in oil","detail":"Commonly blanched then preserved in oil or vinegar in southern Europe."}]'::jsonb),
  ('woolly-milkcap', 'Woolly Milkcap', 'Lactarius torminosus', 'toxic', false, NULL, ARRAY['saffron-milkcap']::text[], 'Causes significant gastrointestinal irritation raw or lightly cooked. Some Nordic and Eastern European traditions salt-cure it for weeks before eating, but this is a specialist process, not general cooking, and mistakes are dangerous.', 'Regularly causes GI illness when eaten without the traditional lengthy salt-curing process.', 'Birch woodland', 'Autumn', 'Northern and Central Europe', ARRAY['https://picsum.photos/seed/woolly-milkcap/800/800']::text[], 'Pale pink cap with a shaggy, woolly, inrolled edge; bleeds white (not orange) milk, unlike the Saffron Milkcap.', '[]'::jsonb),
  ('charcoal-burner', 'Charcoal Burner', 'Russula cyanoxantha', 'edible', false, NULL, ARRAY['emetic-russula']::text[], NULL, 'No significant poisoning history; one of the few Russulas confidently recommended to beginners because its gills feel soft and flexible rather than brittle.', 'Deciduous and mixed woodland', 'Summer to autumn', 'Europe', ARRAY['https://picsum.photos/seed/charcoal-burner/800/800']::text[], 'Cap color is variably purple-green-grey; uniquely among Russulas, its gills feel greasy/flexible rather than chalky and brittle.', '[{"method":"Sauté","detail":"Mild, nutty, and one of the more reliable Russulas in the kitchen. Cooks quickly."},{"method":"Handle gently","detail":"Brittle flesh that breaks easily during transport - carry in a rigid basket."}]'::jsonb),
  ('emetic-russula', 'Emetic Russula (Sickener)', 'Russula emetica', 'toxic', false, NULL, ARRAY['charcoal-burner']::text[], 'Causes rapid-onset vomiting and diarrhea, as the common name suggests. Symptoms are unpleasant but generally self-limiting.', 'A frequent cause of mild-to-moderate GI illness across Europe; the wider Russula genus contains many similar-looking toxic species best avoided without expert identification.', 'Coniferous woodland, often near pine, in sphagnum moss', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/emetic-russula/800/800']::text[], 'Bright cherry-red cap and an intensely peppery, acrid taste (spit out, don''t swallow, when taste-testing) distinguish it, but the Russula genus overall is notoriously difficult even for experienced foragers.', '[]'::jsonb),
  ('wood-blewit', 'Wood Blewit', 'Lepista nuda', 'edible_cooked', true, 'Cook thoroughly; causes GI upset in some people when eaten raw or undercooked.', ARRAY['livid-pinkgill']::text[], NULL, 'Generally safe when cooked and correctly identified; the real risk is misidentifying the toxic Livid Pinkgill as a blewit.', 'Leaf litter in deciduous and mixed woodland, gardens, compost heaps', 'Autumn to early winter', 'Europe, North America', ARRAY['https://picsum.photos/seed/wood-blewit/800/800']::text[], 'Distinctive lilac-violet coloring throughout the cap, gills, and stem when young, fading with age; spore print is pale pink-buff.', '[{"method":"Cook thoroughly (required)","detail":"Must be cooked well - raw or undercooked blewits cause GI upset. Never eat raw, including in salads."},{"method":"Slow cook","detail":"Suits stews and slow braises; the violet colour fades to grey-brown as it cooks, which is expected."}]'::jsonb),
  ('livid-pinkgill', 'Livid Pinkgill', 'Entoloma sinuatum', 'toxic', false, NULL, ARRAY['wood-blewit', 'st-georges-mushroom']::text[], 'Causes severe gastrointestinal illness including prolonged vomiting and diarrhea.', 'One of the most common causes of serious (non-fatal) mushroom poisoning in Europe, typically from confusion with St George''s Mushroom or Wood Blewit.', 'Deciduous woodland, especially near oak', 'Late spring to autumn', 'Europe', ARRAY['https://picsum.photos/seed/livid-pinkgill/800/800']::text[], 'Large, pale, greyish-yellow cap with a mealy smell; spore print is salmon-pink, distinguishing it from the white-spored St George''s Mushroom.', '[]'::jsonb),
  ('st-georges-mushroom', 'St George''s Mushroom', 'Calocybe gambosa', 'edible', false, NULL, ARRAY['livid-pinkgill', 'deadly-fibrecap']::text[], NULL, 'Safe when correctly identified; named for traditionally appearing around St George''s Day (23 April) in spring.', 'Grassland, pastures, woodland edges', 'Spring', 'Europe', ARRAY['https://picsum.photos/seed/st-georges-mushroom/800/800']::text[], 'One of the few common edible mushrooms fruiting in spring, which narrows the field considerably - but always confirm against the Deadly Fibrecap, which shares its season.', '[{"method":"Sauté in butter","detail":"Strong, distinctly mealy flavour that some love and some dislike. Cook simply to judge it first."},{"method":"Use sparingly","detail":"The flavour dominates a dish - use less than you would other mushrooms."}]'::jsonb),
  ('deadly-fibrecap', 'Deadly Fibrecap', 'Inocybe erubescens', 'toxic', false, NULL, ARRAY['st-georges-mushroom']::text[], 'Contains high levels of muscarine, causing profuse sweating, salivation, and blurred vision; can be dangerous or fatal for people with heart or respiratory conditions.', 'A recurring cause of spring poisonings in Europe when confused with St George''s Mushroom.', 'Chalky soil in parks, gardens, and woodland edges', 'Spring to early summer', 'Europe', ARRAY['https://picsum.photos/seed/deadly-fibrecap/800/800']::text[], 'Cap and flesh bruise and age to a reddish-pink, and it has a fibrous rather than smooth cap surface - unlike St George''s Mushroom, which stays creamy white.', '[]'::jsonb),
  ('honey-fungus', 'Honey Fungus', 'Armillaria mellea', 'edible_cooked', true, 'Cook thoroughly and discard the tough stems - raw or undercooked honey fungus causes gastrointestinal upset. Only eat the caps.', ARRAY['funeral-bell', 'sulphur-tuft']::text[], NULL, 'Safe when well-cooked and correctly identified; the serious danger is misidentifying the deadly Funeral Bell, which grows in similar spots.', 'At the base of and on tree stumps and roots, deciduous and coniferous', 'Autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/honey-fungus/800/800']::text[], 'Grows in dense clusters on wood with a cottony ring on the stem and a white spore print - take a spore print and check for the ring before eating anything found on a stump.', '[{"method":"Cook thoroughly (required)","detail":"Must be well cooked. Undercooked honey fungus causes GI upset in many people, and some react even when it is properly cooked."},{"method":"Parboil and discard water","detail":"Commonly parboiled with the water discarded before the final cooking, which reduces the reaction rate."},{"method":"Caps only","detail":"Discard the tough, fibrous stems entirely."}]'::jsonb),
  ('funeral-bell', 'Funeral Bell', 'Galerina marginata', 'deadly', false, NULL, ARRAY['honey-fungus']::text[], 'Contains the same amatoxins as the Death Cap. Small, unassuming, and grows on wood in the same spots foragers look for Honey Fungus.', 'A well-documented cause of fatal poisoning, typically from being mistaken for Honey Fungus or for hallucinogenic Psilocybe species growing in the same habitat.', 'On decaying wood, stumps, and fallen branches, conifer and deciduous', 'Late summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/funeral-bell/800/800']::text[], 'Much smaller and thinner-fleshed than Honey Fungus, grows singly or in small groups rather than dense clusters, and has a rusty-brown (not white) spore print.', '[]'::jsonb),
  ('sulphur-tuft', 'Sulphur Tuft', 'Hypholoma fasciculare', 'toxic', false, NULL, ARRAY['honey-fungus']::text[], 'Intensely bitter and causes gastrointestinal illness including vomiting and diarrhea.', 'Regularly causes mild-to-moderate GI poisoning when picked in place of Honey Fungus.', 'Dense clusters on stumps and dead wood, deciduous and coniferous', 'Year-round, peaking in autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/sulphur-tuft/800/800']::text[], 'Sulphur-yellow cap and gills that turn greenish then purple-black with age (from the spores); intensely bitter taste - unlike the mild Honey Fungus.', '[]'::jsonb),
  ('shaggy-mane', 'Shaggy Mane', 'Coprinus comatus', 'edible', false, 'Eat within hours of picking - the cap self-digests into black ink within a day, especially once picked.', ARRAY['common-inkcap']::text[], NULL, 'Safe on its own; unlike the Common Ink Cap it has no alcohol interaction, but the two are easy to confuse so caution around alcohol is still often advised.', 'Grassy areas, roadsides, disturbed ground', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/shaggy-mane/800/800']::text[], 'Tall, cylindrical, shaggy white cap that dissolves into black ink from the bottom edge upward with age - only eat while still white and firm.', '[{"method":"Cook within hours","detail":"Begins self-digesting into black ink almost immediately after picking. Cook the same day, ideally within a few hours."},{"method":"Gentle sauté or soup","detail":"Delicate, high water content - a quick sauté or a soup suits it better than aggressive frying."}]'::jsonb),
  ('common-inkcap', 'Common Ink Cap', 'Coprinopsis atramentaria', 'toxic', false, NULL, ARRAY['shaggy-mane']::text[], 'Contains coprine, which is harmless alone but blocks alcohol metabolism. Combined with alcohol - even consumed up to several days after eating the mushroom - it causes flushing, rapid heartbeat, nausea, and vomiting (a reaction historically nicknamed ''tippler''s bane'').', 'A very well-documented and specific poisoning pattern tied to alcohol consumption after eating the mushroom, rather than the mushroom itself.', 'Grassy areas, disturbed ground, near tree stumps', 'Spring to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/common-inkcap/800/800']::text[], 'Greyish, less shaggy cap than Shaggy Mane, growing in dense clumps; if you eat any ink cap, avoid alcohol entirely for several days afterward.', '[]'::jsonb),
  ('oyster-mushroom', 'Oyster Mushroom', 'Pleurotus ostreatus', 'edible', false, NULL, '{}', NULL, 'No significant poisoning history; widely foraged and commercially cultivated.', 'Growing in shelf-like clusters on dead or dying deciduous trees', 'Autumn to early spring', 'Europe, North America', ARRAY['https://picsum.photos/seed/oyster-mushroom/800/800']::text[], 'Fan- or oyster-shaped cap growing directly from wood in overlapping shelves, with gills running down a short or absent stem.', '[{"method":"High-heat sear","detail":"Sears beautifully and crisps at the edges. Do not crowd the pan or they steam instead of browning."},{"method":"Shred and fry","detail":"Tearing rather than slicing gives more surface area and a better texture."}]'::jsonb),
  ('chicken-of-the-woods', 'Chicken of the Woods', 'Laetiporus sulphureus', 'edible_cooked', true, 'Cook thoroughly - raw or undercooked specimens can cause GI reactions. Avoid specimens growing on yew, eucalyptus, or other trees known to concentrate toxins into the fungus.', '{}', NULL, 'Generally well tolerated when cooked and harvested young from a safe host tree, though some people experience allergic-type reactions.', 'Growing in shelf-like clusters on living or dead deciduous trees, especially oak', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/chicken-of-the-woods/800/800']::text[], 'Bright orange-yellow overlapping shelf-like brackets on a tree trunk; unmistakable coloring, but note the host tree species before eating.', '[{"method":"Cook thoroughly (required)","detail":"Always cook well - undercooked specimens cause GI reactions, and some people react regardless. Try a small portion the first time."},{"method":"Young edges only","detail":"Use the soft outer growing edges. The older inner bracket turns woody and chalky."},{"method":"Check the host tree","detail":"Avoid specimens growing on yew, eucalyptus, or conifers - the fungus can take up compounds from the host."}]'::jsonb),
  ('beefsteak-fungus', 'Beefsteak Fungus', 'Fistulina hepatica', 'edible', false, NULL, '{}', NULL, 'No significant poisoning history.', 'On living oak and sweet chestnut trunks', 'Late summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/beefsteak-fungus/800/800']::text[], 'Resembles a slab of raw meat, complete with a red juice that runs when cut - visually distinctive.', '[{"method":"Slice thin","detail":"Acidic and quite sour, unlike most mushrooms. Slicing thin and cooking in fat mellows it."},{"method":"Soak to reduce acidity","detail":"Some cooks soak slices in milk or water before cooking to draw out the sourness."}]'::jsonb),
  ('panther-cap', 'Panther Cap', 'Amanita pantherina', 'toxic', false, NULL, ARRAY['blusher']::text[], 'Contains ibotenic acid and muscimol, causing confusion, disorientation, and in higher doses more severe neurological effects; potentially life-threatening in vulnerable people. Not a culinary species.', 'A recurring cause of poisoning in Central Europe, especially when confused with the edible Blusher.', 'Deciduous and coniferous woodland', 'Summer to autumn', 'Europe', ARRAY['https://picsum.photos/seed/panther-cap/800/800']::text[], 'Brown cap with white warts, a distinct bulbous stem base with a rimmed collar (not a loose sack-like volva), and flesh that does NOT redden when cut or bruised - unlike the Blusher.', '[]'::jsonb),
  ('blusher', 'The Blusher', 'Amanita rubescens', 'edible_cooked', true, 'Cook thoroughly - raw or undercooked specimens are mildly toxic. Given how easily it is confused with dangerous Amanita species, this one is recommended for experienced foragers only.', ARRAY['panther-cap', 'death-cap']::text[], 'Safe once well-cooked, but belongs to the same genus as the deadliest mushrooms in Europe and should only be picked by foragers confident in Amanita identification.', 'Poisonings attributed to this species are almost always cases of a more dangerous Amanita picked by mistake.', 'Deciduous and coniferous woodland', 'Summer to autumn', 'Europe', ARRAY['https://picsum.photos/seed/blusher/800/800']::text[], 'Flesh reddens (''blushes'') distinctly where bruised or cut, especially at the stem base - a feature the dangerous Panther Cap and Death Cap do not share.', '[{"method":"Cook thoroughly (required)","detail":"Raw or undercooked Blushers are toxic. Cook completely - and only if you are certain of the identification, since this is an Amanita."},{"method":"Simple sauté","detail":"Good texture and mild flavour once well cooked. Suits a plain butter sauté."}]'::jsonb),
  ('fly-agaric', 'Fly Agaric', 'Amanita muscaria', 'toxic', false, NULL, ARRAY['blusher']::text[], 'Contains ibotenic acid and muscimol; causes neurotoxic effects including confusion, altered perception, and nausea. Not a culinary species regardless of traditional detoxification methods used elsewhere.', 'A frequent cause of accidental poisoning, especially in children, due to its bright red, highly recognizable but tempting appearance.', 'Birch and pine woodland', 'Autumn', 'Europe, North America (introduced)', ARRAY['https://picsum.photos/seed/fly-agaric/800/800']::text[], 'Iconic bright red cap with white warts - the most recognizable mushroom in Europe, and a good reminder that recognizability doesn''t mean edibility.', '[]'::jsonb),
  ('brown-rollrim', 'Brown Rollrim', 'Paxillus involutus', 'toxic', false, NULL, '{}', 'Once widely eaten after cooking and long believed safe, it is now known to trigger a potentially fatal autoimmune reaction (destroying red blood cells) in some people after repeated exposure, with no way to predict who is affected.', 'Historically a significant cause of mushroom-poisoning deaths in Europe, notably before the delayed autoimmune mechanism was understood in the 20th century.', 'Deciduous and coniferous woodland, often near birch', 'Summer to autumn', 'Europe', ARRAY['https://picsum.photos/seed/brown-rollrim/800/800']::text[], 'Inrolled, brown, felty cap margin and gills that bruise brown when touched; a textbook example of why ''my grandparents always ate this'' is not a safety guarantee.', '[]'::jsonb),
  ('poison-pie', 'Poison Pie', 'Hebeloma crustuliniforme', 'toxic', false, NULL, '{}', 'Causes gastrointestinal upset including nausea and vomiting.', 'A recurring but rarely serious cause of GI poisoning in Europe.', 'Deciduous and coniferous woodland, parks', 'Autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/poison-pie/800/800']::text[], 'Pale tan cap with a sweet, radish-like smell that belies its toxicity - smell is not a reliable safety test.', '[]'::jsonb),
  ('verdigris-agaric', 'Verdigris Agaric', 'Stropharia aeruginosa', 'unknown', false, NULL, '{}', 'Edibility is disputed in the mycological literature - some sources list it as edible after cooking, others report GI upset. Not recommended given the inconsistent reports.', 'Occasional reports of mild GI upset; not well studied enough to recommend confidently either way.', 'Grassland, woodland edges, on decaying plant matter', 'Summer to autumn', 'Europe, North America', ARRAY['https://picsum.photos/seed/verdigris-agaric/800/800']::text[], 'Striking blue-green, slimy cap makes it easy to recognize even though its edibility status remains unsettled.', '[]'::jsonb)
